-- All model-routing storage (docs/model-routing-design.md §7), shared by P1–P5.
-- UUID v7 ids are generated by Prisma, as on the existing task and workspace tables.
BEGIN;

ALTER TABLE "task"
  ADD COLUMN "model_hint" TEXT,
  ADD COLUMN "model_hint_reason" TEXT,
  ADD CONSTRAINT "task_model_hint_check"
    CHECK ("model_hint" IS NULL OR "model_hint" IN ('S', 'M', 'L', 'XL'));

ALTER TABLE "workspace"
  ADD COLUMN "model_routing" BOOLEAN NOT NULL DEFAULT false,
  ADD COLUMN "model_routing_providers" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[];

CREATE TABLE "task_route_decision" (
  "id" UUID NOT NULL,
  "owner_id" UUID NOT NULL,
  "task_id" UUID NOT NULL,
  "request_token" TEXT NOT NULL,
  -- Decisions precede session creation; rejected dispatches may never create the session.
  "session_id" UUID,
  "applied" BOOLEAN NOT NULL,
  "policy_version" INTEGER NOT NULL,
  "level" TEXT,
  "provider" TEXT NOT NULL,
  "model" TEXT,
  "effort" TEXT,
  "baseline" JSONB NOT NULL,
  "features" JSONB NOT NULL,
  "reasons" TEXT[] NOT NULL,
  "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "task_route_decision_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "task_route_decision_level_check"
    CHECK ("level" IS NULL OR "level" IN ('S', 'M', 'L', 'XL')),
  CONSTRAINT "task_route_decision_task_id_request_token_key" UNIQUE ("task_id", "request_token"),
  CONSTRAINT "task_route_decision_owner_id_fkey" FOREIGN KEY ("owner_id")
    REFERENCES "user" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "task_route_decision_task_id_fkey" FOREIGN KEY ("task_id")
    REFERENCES "task" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE INDEX "task_route_decision_owner_id_created_at_idx"
  ON "task_route_decision" ("owner_id", "created_at");
CREATE INDEX "task_route_decision_session_id_idx"
  ON "task_route_decision" ("session_id");

COMMIT;
